<?php require_once "includes/db.php";$id=(int)($_GET["id"]??0);$stmt=$conn->prepare("SELECT * FROM properties WHERE id=?");$stmt->execute([$id]);$p=$stmt->fetch(PDO::FETCH_ASSOC);if(!$p){header("Location:index.php");exit;}$page_title=$p["name"];include "includes/header.php";$services=array_filter(array_map("trim",explode(",",$p["services"]??""))); ?>
